<script setup lang="ts">
import { ref } from 'vue'
import { useWorkspace } from '../stores/workspace'

type SimulationResult = { feasible: boolean; min_balance_cents: number; min_day: number; assumptions: { floor_cents: number; goal_cents: number; [key: string]: number }; points_cents: number[]; events: Array<{ day: number; source: string; signed_cents: number; [key: string]: unknown }> }
const workspace = useWorkspace(); const salaryDay = ref(17); const purchaseDay = ref(19); const dailyBudget = ref(8000); const floor = ref(300000); const goal = ref(600000); const result = ref<SimulationResult | null>(null); const assumptions = ref<string[]>([]); const error = ref(''); const loading = ref(false)
function money(value: unknown) { const numeric = Number(value); return Number.isFinite(numeric) ? `¥${(numeric / 100).toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : '—' }
function points() { return Array.isArray(result.value?.points_cents) ? result.value?.points_cents as number[] : [] }
function pointPath() { const values = points(); if (!values.length) return ''; const max = Math.max(...values, floor.value); const min = Math.min(...values, floor.value); return values.map((value, index) => `${index ? 'L' : 'M'} ${20 + index * 560 / Math.max(1, values.length - 1)} ${18 + (max - value) * 155 / Math.max(1, max - min)}`).join(' ') }
function floorY() { const values = points(); if (!values.length) return 173; const max = Math.max(...values, floor.value); const min = Math.min(...values, floor.value); return 18 + (max - floor.value) * 155 / Math.max(1, max - min) }
async function simulate() {
  loading.value = true; error.value = ''; result.value = null; assumptions.value = []
  try { const response = await workspace.simulate('demo-goal', { salary_day: salaryDay.value, purchase_day: purchaseDay.value, daily_budget_cents: dailyBudget.value, floor_cents: floor.value, goal_cents: goal.value }); result.value = response.result as SimulationResult; assumptions.value = response.assumptions || [] }
  catch (caught) { error.value = caught instanceof Error ? caught.message : '模拟失败，请重试。' }
  finally { loading.value = false }
}
</script>
<template><section class="card page-card future-page"><span class="eyebrow">DETERMINISTIC CASHFLOW</span><h1>未来账本</h1><p>LLM 只提取目标和约束；余额、日期和可行性由后端确定性模拟，不会自动执行转账。</p><div class="plan-form"><label>工资日<input v-model.number="salaryDay" type="number" min="1" max="30"></label><label>购买日<input v-model.number="purchaseDay" type="number" min="1" max="30"></label><label>每日预算（分）<input v-model.number="dailyBudget" type="number" min="0"></label><label>最低保留（分）<input v-model.number="floor" type="number" min="0"></label><label>目标金额（分）<input v-model.number="goal" type="number" min="0"></label></div><button class="primary-button" :disabled="loading" @click="simulate">{{ loading ? '模拟中…' : '运行 30 天现金流模拟' }}</button><p v-if="error" class="auth-error">{{ error }}</p><div v-if="result" class="simulation-result"><div class="simulation-head"><div><b>模拟完成</b><small>{{ result.feasible ? '当前假设不会跌破最低保留余额' : '当前假设会跌破最低保留余额' }}</small></div><span :class="['feasibility', result.feasible ? 'ok' : 'bad']">{{ result.feasible ? '可行' : '需调整' }}</span></div><ul class="simulation-assumptions"><li v-for="item in assumptions" :key="item">{{ item }}</li><li>期初余额：{{ money(result.assumptions?.opening_balance_cents) }}</li></ul><div class="simulation-cards"><div><small>最低余额</small><strong>{{ money(result.min_balance_cents) }}</strong><span>第{{ result.min_day }}天</span></div><div><small>最低保留</small><strong>{{ money(result.assumptions?.floor_cents) }}</strong><span>保护约束</span></div><div><small>目标金额</small><strong>{{ money(result.assumptions?.goal_cents) }}</strong><span>电脑目标</span></div></div><div class="cashflow-chart"><div class="visual-title">30天日终余额</div><svg viewBox="0 0 600 205" class="result-chart"><line x1="20" y1="18" x2="20" y2="173" stroke="#dfe9e5"/><line x1="20" y1="173" x2="580" y2="173" stroke="#dfe9e5"/><line x1="20" :y1="floorY()" x2="580" :y2="floorY()" stroke="#d59b58" stroke-dasharray="5 5"/><path :d="pointPath()" fill="none" stroke="#087d68" stroke-width="3" stroke-linecap="round"/></svg><div class="chart-legend"><span><i class="legend-income"></i>模拟余额</span><span><i style="background:#d59b58"></i>最低保留余额</span></div></div><details class="simulation-details"><summary>查看事件与假设</summary><div class="event-list"><div v-for="event in result.events || []" :key="`${event.day}-${event.source}`"><span>第{{ event.day }}天</span><b>{{ event.source }}</b><strong>{{ event.signed_cents > 0 ? '+' : '' }}{{ money(event.signed_cents) }}</strong></div></div></details></div></section></template>
